<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use Override;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkEnabledGateway;

final class InMemoryMagicLinkEnabledGateway implements MagicLinkEnabledGateway
{
    /** @var array<string, bool> keyed by tenantName */
    private array $enabledByTenant = [];

    public function enable(string $tenantName): void
    {
        $this->enabledByTenant[$tenantName] = true;
    }

    public function disable(string $tenantName): void
    {
        $this->enabledByTenant[$tenantName] = false;
    }

    #[Override]
    public function isEnabled(string $tenantName): bool
    {
        return $this->enabledByTenant[$tenantName] ?? false;
    }
}
